import { getRequestHeaders } from "h3";
import { ensureConfiguration, readBodyClone } from "../helpers.js";
const baseAPI = import.meta.dev ? "https://api-m.sandbox.paypal.com/v1" : "https://api-m.paypal.com/v1";
export const isValidPaypalWebhook = async (event) => {
  const config = ensureConfiguration("paypal", event);
  const headers = getRequestHeaders(event);
  const body = await readBodyClone(event);
  if (!body || !headers) return false;
  const basicAuth = btoa(`${config.clientId}:${config.secretKey}`);
  const endpoint = `${baseAPI}/notifications/verify-webhook-signature`;
  const response = await $fetch(endpoint, {
    method: "POST",
    headers: {
      Authorization: `Basic ${basicAuth}`
    },
    body: {
      auth_algo: headers["paypal-auth-algo"],
      cert_url: headers["paypal-cert-url"],
      transmission_id: headers["paypal-transmission-id"],
      transmission_sig: headers["paypal-transmission-sig"],
      transmission_time: headers["paypal-transmission-time"],
      webhook_id: config.webhookId,
      webhook_event: body
    }
  }).catch(() => null);
  if (!response) return false;
  return response.verification_status === "SUCCESS";
};
